// TH14 v1.00b Stage 3 mid-stage wave 8 (second reward wave), rank0-3.
// Source: st03.ecl.txt:673-706 MainSub05 (entry);
//         st03.ecl.txt:8-31   ECir00   (enemy closure);
//         st03.ecl.txt:33-87  ECir00_at (laser fan closure).

const TIME_LIMIT: int = 2124;      // 120 opening + 2000 source window + 4 start slack
const OPENING_BUFFER: int = 120;
const LASER_COLOR: int = 3;        // etSprite(0, 20, 3); laser collision ignores color
const LASER_W: fx = 7fx;           // laserNew width 14 (<32): Line half-height 14/4=3.5

// ECir00_at: one sweeping fan of Line lasers from the enemy's current position.
// Source sets the emitter once (etSprite/etAngle/etSpeed/laserNew), then per shot
// does etAngle(A), A += F1, laserOn, wait(gap) while B--.
async sub ecir00_at(a0: angle, step: angle) {
    var shots: int = 11;           // diffI($B, 11, 16, 20, 24)
    var spd: fx = 2.7fx;           // etSpeed !E 2.7 / !N 3.0 / !H 4.0 / !LO 5.0
    var len: fx = 128fx;           // laserNew targetLength !E 128 / !N 128 / !H 144 / !LO 160
    var gap: int = 7;              // wait(!E 7 / !N 5 / !H 4 / !LO 4)
    var r: int = global(GVAR_RANK);
    if r == 1 { shots = 16; spd = 3fx; gap = 5; }
    if r == 2 { shots = 20; spd = 4fx; len = 144fx; gap = 4; }
    if r == 3 { shots = 24; spd = 5fx; len = 160fx; gap = 4; }

    // Line judged segment for flags 0x2 clear: origin+L/10 .. origin+0.9L.
    // Grow the far end at the source speed, so the on-line growth phase keeps
    // the same 0.8L judged length; the rod then flies out and self-recycles.
    var near: fx = len / 10;
    var rod: fx = len * 8 / 10;
    var a: angle = a0;
    for i in 0..shots {
        var h: int = laser(LASER_COLOR, $self_x, $self_y, a, 0fx, LASER_W, 0, 9999, 0);
        lz_start(h, near);
        lz_speed(h, spd, rod);
        a = a + step;
        wait(gap);
    }
}

// ECir00: enter from the parent's F0/F1, dive toward the player, fire the fan
// 40 frames in, then re-aim and drift. Source never deletes (1000-frame loop).
async sub ecir00(f0: angle, f1: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);             // setHurtbox(24, 24): circle branch 24*0.5
    set_hitbox(8fx);               // setHitbox(16, 16): circle branch 16*0.5
    move_vel(0, aim_player(), 3fx, EASE_LINEAR);   // moveVel(ANGLE_PLAYER, 3.0)
    move_speed(40, 0fx, EASE_QUAD_IN);             // moveSpeedTime(40, 1, 0.0)
    wait(40);
    spawn ecir00_at(f0, f1);       // @ECir00_at(%F0) async
    wait(60);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(ANGLE_PLAYER, 0.0)
    move_speed(120, 2fx, EASE_QUAD_IN);            // moveSpeedTime(120, 1, 2.0)
    loop { wait(1000); }
}

// MainSub05: eight ECir00 in mirrored pairs. F0 is the fan base angle, F1 the
// per-shot turn (radians -> BAM); source pairs create on the same frame.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(60);
    _ = spawn_enemy(128fx, -32fx, 1000, 0, 0, 0, ecir00(180deg, -20deg));   // F1 -0.349066
    _ = spawn_enemy(-128fx, -32fx, 1000, 0, 0, 0, ecir00(0deg, 20deg));
    wait(60);
    _ = spawn_enemy(64fx, -32fx, 1000, 0, 0, 0, ecir00(180deg, -19deg));    // F1 -0.331613
    wait(40);
    _ = spawn_enemy(-64fx, -32fx, 1000, 0, 0, 0, ecir00(0deg, 19deg));
    wait(80);
    _ = spawn_enemy(160fx, -32fx, 1000, 0, 0, 0, ecir00(180deg, -18deg));   // F1 -0.314159
    wait(40);
    _ = spawn_enemy(-160fx, -32fx, 1000, 0, 0, 0, ecir00(0deg, 18deg));
    wait(40);
    _ = spawn_enemy(128fx, -32fx, 1000, 0, 0, 0, ecir00(180deg, -20deg));
    _ = spawn_enemy(-128fx, -32fx, 1000, 0, 0, 0, ecir00(0deg, 20deg));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
